import{_ as e,o as t,c as r,a4 as l}from"./chunks/framework.9tZL7ZIQ.js";const h=JSON.parse('{"title":"比尔·安德斯","description":"","frontmatter":{"title":"比尔·安德斯","date":"2026-04-13T00:00:00.000Z"},"headers":[],"relativePath":"04_people/比尔·安德斯.md","filePath":"04_people/比尔·安德斯.md"}'),o={name:"04_people/比尔·安德斯.md"};function i(n,a,s,_,p,c){return t(),r("div",null,[...a[0]||(a[0]=[l('<h1 id="比尔·安德斯" tabindex="-1">比尔·安德斯 <a class="header-anchor" href="#比尔·安德斯" aria-label="Permalink to &quot;比尔·安德斯&quot;">​</a></h1><ul><li><strong>角色职位</strong>：通用动力公司（General Dynamics）CEO</li><li><strong>与巴菲特关系</strong>：1994年伯克希尔·哈撒韦收购通用动力时任 CEO</li></ul><h2 id="主要事迹" tabindex="-1">主要事迹 <a class="header-anchor" href="#主要事迹" aria-label="Permalink to &quot;主要事迹&quot;">​</a></h2><p>比尔·安德斯在1994年担任通用动力公司（General Dynamics）CEO 期间，与巴菲特完成了一笔令华尔街瞩目的交易——伯克希尔·哈撒韦收购了通用动力的大部分股份。通用动力是美国最大的国防承包商之一，业务涵盖军用飞机、坦克、潜艇及信息系统等多个领域。</p><p>在安德斯的领导下，通用动力经历了重要的战略重组。1990年代初冷战结束，美国国防预算缩减，通用动力面临订单减少的压力。安德斯主导了公司的业务精简与资产重组，聚焦核心国防业务，出售非核心资产，使公司在行业调整期保持了财务健康。</p><p>巴菲特对通用动力的投资时机堪称精准。1994年，在国防行业低谷期，伯克希尔以有吸引力的价格收购了通用动力约 $300 万股（后增持至约 $700 万股）。安德斯作为当时的 CEO，其战略判断力和执行能力给巴菲特留下了深刻印象。这笔投资后来为伯克希尔带来了可观的回报，也是巴菲特在非常时期逆向投资优质企业的经典案例之一。</p><h2 id="关键年份事件" tabindex="-1">关键年份事件 <a class="header-anchor" href="#关键年份事件" aria-label="Permalink to &quot;关键年份事件&quot;">​</a></h2><ul><li><strong>1991年</strong>：被任命为通用动力公司 CEO，负责公司在冷战后的战略转型</li><li><strong>1994年</strong>：伯克希尔·哈撒韦收购通用动力，成为当时巴菲特最大的一笔投资之一</li><li><strong>后续</strong>：通用动力在安德斯及后续管理层的带领下，股价表现强劲，伯克希尔在此投资上获利丰厚</li></ul><h2 id="关键原文出处" tabindex="-1">关键原文出处 <a class="header-anchor" href="#关键原文出处" aria-label="Permalink to &quot;关键原文出处&quot;">​</a></h2><p>以下为该人物在致股东信中被提及的关键年份，点击即可阅读完整翻译：</p><ul><li><a href="/search?q=比尔·安德斯在1992年股东信中的原话">1992年：完整翻译|/01_letters/1992年/翻译</a></li></ul>',11)])])}const u=e(o,[["render",i]]);export{h as __pageData,u as default};
